from lib import *
S = SS('g42')
steps = [
    step("size class 表(internal/runtime/gc/sizeclasses.go 开头的注释,Go 1.27.1):共 68 个 class(NumSizeClasses = 68),最小 8 字节,最大 32768 字节(MaxSmallSize),TinySize = 16,页大小 1 << 13 = 8 KiB(PageShift = 13);每个 class 有固定的“对象大小、每个 span 的字节数、每个 span 放几个对象、尾部浪费、最大浪费比例”。例如 class 1 是 8 字节 × 1024 个/8192 字节的 span;class 3 是 24 字节 × 341 个,尾部浪费 8 字节;class 5 是 48 字节 × 170 个,尾部浪费 32 字节,最大浪费 31.52%;class 67 是 32768 字节 × 1 个。MinSizeForMallocHeader = 指针大小 × 指针位数。", t=tl(S(1)), done=lidx(S(1), 'class  bytes/obj', '     1          8', '     2         16'), mark=lidx(S(1), 'MaxSmallSize', 'NumSizeClasses', 'TinySize', 'PageShift', 'MinSizeForMallocHeader'), kv=KV([['class 数', '68 个,8 字节到 32768 字节'], ['span', '多为 8 KiB(1 页),大对象 class 的 span 更大'], ['TinySize', '16 字节'], ['页', '8 KiB(PageShift = 13)']], ['class 数'])),
    step("请求的大小落在哪个 size class(MemStats.BySize 分配前后的差,每个大小分配 2 万个并保留):9 字节 → 16 字节 class;17 → 24;25 → 32;33 → 48;49 → 64;65 → 80;100 → 112;200 → 208;600 → 640;1030 → 1152;5000 → 5376;16000 → 16384。浪费比例从 93.8%(1 字节)到 2.3%(16000 字节)。1 字节与 8 字节的请求对应的 16 字节 class 只多出 1250 次与 10000 次分配(而不是 20000 次),因为它们被 tiny 分配器合并了:16 个 1 字节对象共用一个 16 字节块,2 个 8 字节对象共用一个。", t=tl(S(2)), done=lidx(S(2), '请求     9 字节', '请求    17 字节', '请求   100 字节'), mark=lidx(S(2), '请求     1 字节', '请求     8 字节', '请求  1030 字节', '请求 16000 字节'), b=bars([['17 字节 → 24', 24, '24'], ['33 字节 → 48', 48, '48'], ['1030 字节 → 1152', 1152, '1152'], ['16000 字节 → 16384', 16384, '16384']], 16384, done=[0, 1, 2, 3]), kv=KV([['9 / 17 / 25 / 33 / 49 / 65 字节', '16 / 24 / 32 / 48 / 64 / 80 字节 class'], ['600 / 1030 / 5000 字节', '640 / 1152 / 5376 字节 class'], ['1 字节与 8 字节请求', '16 字节 class 只多 1250 / 10000 次:tiny 合并'], ['浪费', '1 字节 93.8%(未合并时),16000 字节 2.3%']], ['1 字节与 8 字节请求'])),
    step("tiny 分配器:100 万个对象各自保留,扣掉 []any 每个槽 16 字节之后,每个对象占堆:new(byte) 1.0 字节、new(int32) 4.0、new(int64) 8.0、含指针的 8 字节结构 8.0——小对象确实被紧凑地放在一起;new([9]byte) 与 new([12]byte) 各占 16.0 字节(放不下第二个,各用一个 16 字节块);new([16]byte) 16.0、new([17]byte) 24.0(进入 24 字节 class)、new(T24) 24.0。", t=tl(S(3)), done=lidx(S(3), 'new(byte)', 'new(int32)', 'new(int64)'), mark=lidx(S(3), 'new([9]byte)', 'new([12]byte)', 'new([17]byte)'), b=bars([['new(byte)', 1, '1 字节'], ['new(int32)', 4, '4 字节'], ['new(int64)', 8, '8 字节'], ['new([9]byte)', 16, '16 字节'], ['new([17]byte)', 24, '24 字节']], 24, done=[0, 1, 2], mark=[3, 4]), kv=KV([['1 / 4 / 8 字节(不含指针)', '各占 1 / 4 / 8 字节:合并进 16 字节块'], ['9 / 12 字节(不含指针)', '各占 16 字节:一个块放不下两个'], ['17 字节', '24 字节(24 字节 class)']], ['9 / 12 字节(不含指针)'])),
    step("malloc header:含指针的对象大于 512 字节要多 8 字节存类型信息。每个对象占堆(已扣 []any 开销):[64]*int(512 字节,含指针)512.0 字节(没有 header);[65]*int(520 字节,含指针)576.0;[72]*int(576 字节,含指针)639.9(≈640 字节 class),而 [72]int(576 字节,不含指针)575.9;[128]*int(1024 字节,含指针)1151.9(≈1152 字节 class),而 [128]int 1023.9。", t=tl(S(4)), done=lidx(S(4), '[64]*int'), mark=lidx(S(4), '[72]*int', '[128]*int'), b=bars([['[72]*int(含指针)', 640, '640'], ['[72]int(不含指针)', 576, '576'], ['[128]*int(含指针)', 1152, '1152'], ['[128]int(不含指针)', 1024, '1024']], 1152, done=[1, 3], mark=[0, 2]), kv=KV([['512 字节含指针', '512,没有 header'], ['576 字节含指针 vs 不含', '640 vs 576'], ['1024 字节含指针 vs 不含', '1152 vs 1024'], ['原因', 'MinSizeForMallocHeader = 512:更大的含指针对象在头部多存一个 8 字节的类型头']], ['原因'])),
    step("大于 32 KiB 的对象直接从页堆分配,按 8 KiB 页取整(扣掉每个 24 字节的切片头):make([]byte, 32768) 约 32771 字节 = 4.00 页;32769 → 40962 = 5.00 页;33000 → 40960 = 5.00 页;40960 → 40960 = 5.00 页;40961 → 49152 = 6.00 页;65536 → 65536 = 8.00 页;100000 → 106496 = 13.00 页。", t=tl(S(5)), done=lidx(S(5), 'make([]byte,  32768)', 'make([]byte,  40960)'), mark=lidx(S(5), '32769', '40961', '100000'), kv=KV([['32768 字节', '4 页(恰好整页)'], ['32769 / 33000 / 40960 字节', '都是 5 页 = 40960 字节'], ['40961 字节', '6 页 = 49152 字节'], ['100000 字节', '13 页 = 106496 字节']], ['32769 / 33000 / 40960 字节'])),
    step("分配成本随大小(每次分配 n 字节的切片并保留引用,5 轮取中位数):8 字节 7.1 ns、16 字节 7.7、32 字节 8.8、64 字节 11.3、128 字节 70.5、512 字节 101.9、1024 字节 146.3、4096 字节 408.1、16384 字节 1255.7、32768 字节 2026.5、65536 字节 3417.0、262144 字节 8436.5 ns/次。同一份代码用 GOEXPERIMENT=nosizespecializedmalloc 构建:8 字节 8.2、16 字节 10.7、32 字节 12.8、64 字节 14.6 ns,128 字节以上几乎相同(70.1、100.5、145.4)——ToolTags 里默认带 goexperiment.sizespecializedmalloc,它让 64 字节以内的分配快约 1–4 ns。", t=tl(S(6)), done=lidx(S(6), 'make([]byte,      8)', 'make([]byte,     64)'), mark=lidx(S(6), 'make([]byte,    128)', 'nosizespecializedmalloc', 'make([]byte, 262144)'), b=bars([['8 字节', 7.1, '7.1'], ['64 字节', 11.3, '11.3'], ['128 字节', 70.5, '70.5'], ['1024 字节', 146.3, '146.3'], ['16384 字节', 1255.7, '1256']], 1255.7, done=[0, 1], mark=[2, 3, 4]), kv=KV([['≤ 64 字节', '7–11 ns(nosizespecializedmalloc 时 8–15 ns)'], ['128 字节起', '70 ns 以上,1 KiB 146 ns,16 KiB 约 1.26 µs'], ['> 32 KiB', '64 KiB 3.4 µs,256 KiB 8.4 µs']], ['≤ 64 字节'])),
    step("成本并不随大小单调:每次分配直接放进全局变量,64 字节 10.8 ns、80 字节 12.6、96 字节 17.3、112 字节 18.2;120 字节 70.7、128 字节 69.6(120 落在 128 字节 class);144 字节又回到 23.1;192 字节 74.9、256 字节 78.1 ns。某些 class(128、192、256)比相邻 class 慢得多,我没有查明原因。", t=tl(S(7)), done=lidx(S(7), 'make([]byte,  64)', 'make([]byte, 112)'), mark=lidx(S(7), 'make([]byte, 120)', 'make([]byte, 128)', 'make([]byte, 144)', 'make([]byte, 192)'), b=bars([['112 字节', 18.2, '18.2'], ['128 字节', 69.6, '69.6'], ['144 字节', 23.1, '23.1'], ['192 字节', 74.9, '74.9']], 74.9, done=[0, 2], mark=[1, 3]), kv=KV([['112 → 128 → 144 字节', '18.2 → 69.6 → 23.1 ns(不单调)'], ['192 / 256 字节', '74.9 / 78.1 ns'], ['原因', '没有查明(未验证)']], ['112 → 128 → 144 字节'])),
]
A = mkartg('g42', 42, 'Go,内存分配器,size class,tiny 分配器,malloc header,真实验证,动画演示',
    '在 Go 1.27.1 里用 MemStats.BySize、堆增量与基准测试验证内存分配器:68 个 size class(8 到 32768 字节,页 8 KiB);请求大小向上取整到 class(17 字节 → 24,1030 → 1152);小于 16 字节的无指针对象被 tiny 分配器合并(1 字节对象只占 1 字节);含指针的对象大于 512 字节要多 8 字节 malloc header(576 字节含指针占 640);大于 32 KiB 按 8 KiB 页取整;分配成本从 8 字节的 7 ns 到 256 KiB 的 8.4 µs,并且在 128、192、256 字节处出现无法解释的跳变。',
    '“Go 的 new 和 make 到底占多少内存”要看分配器:它把小对象按 68 个固定大小的 class 分配,超过 32 KiB 的对象直接从页堆取页。这篇逐个验证:class 表、取整与浪费、tiny 分配器、malloc header、大对象的页取整,以及不同大小的分配耗时(包括一个我没有查明的非单调现象)。',
    [('68 个', 'size class 的数量,8 字节到 32768 字节'), ('640 vs 576', '576 字节的数组:含指针时占 640 字节(多 8 字节 header 后落入下一个 class),不含指针 576 字节'), ('1 字节', 'tiny 分配器下 new(byte) 实际占的堆:16 个共用一个 16 字节块')],
    [('size class 表', '<p>运行时把 8 字节到 32 KiB 之间的对象分成 68 个固定大小的 class;每个 class 的内存由若干个 8 KiB 页组成的 span 提供,span 里按对象大小切开。class 的步长在小处是 8 或 16 字节,在大处是 1 KiB 以上,表里的“max waste”列给出每个 class 的最大浪费比例(小 class 可高达 87.5%,大多数 class 在 5% 到 30% 之间)。</p>'),
     ('请求大小向上取整', '<p>请求的字节数向上取整到最近的 class,例如 17 → 24、33 → 48、1030 → 1152。上面实测的落点与表一致。这意味着“结构体多一个字段”有时一个字节都不多占,有时跨过 class 边界多占几十字节——可以用上一篇结构体对齐里的方法算好再取舍。</p>'),
     ('tiny 分配器', '<p>不含指针、小于 16 字节的对象不独占一个 class 槽,而是顺序放进同一个 16 字节块。实验里 <code>new(byte)</code> 每个只占 1 字节(2 万次分配只多了 1250 个 16 字节块的分配),<code>new(int64)</code> 占 8 字节。放不下第二个的 <code>[9]byte</code>、<code>[12]byte</code> 各占一个 16 字节块。含指针的对象不走 tiny(要给 GC 精确的指针信息)。</p>'),
     ('malloc header', '<p>常量 <code>MinSizeForMallocHeader</code> 是 512(指针大小 × 指针位数)。含指针且大于 512 字节的对象,实测要多占 8 字节(源码里把它叫 malloc header,内容是什么我没有核对);不含指针的对象没有这个开销。所以 576 字节的含指针数组(加 header 后 584)落入 640 字节的 class,不含指针的只占 576。含指针的大数组/结构体比想象的更占内存。</p>'),
     ('大对象', '<p>大于 32 KiB 的对象不走 size class,直接从页堆取整数个 8 KiB 页:33000 字节占 5 页(40960),恰好 40960 也是 5 页,40961 就是 6 页。大对象分配成本高(65536 字节约 3.4 µs),而且零值初始化要清整块内存。</p>'),
     ('分配成本', '<p>小对象(≤ 64 字节)分配只要 7 到 11 ns;1 KiB 约 146 ns;16 KiB 约 1.26 µs;成本大致随字节数增长(包含清零与摊销的 GC 成本)。默认启用的 <code>goexperiment.sizespecializedmalloc</code> 让 ≤ 64 字节的分配快 1 到 4 ns(用 <code>nosizespecializedmalloc</code> 重新构建对比得到)。</p>'),
     ('一个没有解释的现象', '<p>相邻大小的分配耗时并不单调:112 字节 18 ns、128 字节 70 ns、144 字节 23 ns、192 字节 75 ns。可能与不同 class 在 span 中的布局或清零方式有关,但我没有查源码或做对照实验,这里只记录现象。如果你的热路径分配大小恰好落在慢的 class 上,值得在自己的机器上量一量。</p>')],
    steps,
    [ENV_G + '。class 表是 internal/runtime/gc/sizeclasses.go 的原样摘录;落点用 MemStats.BySize 在分配前后的差统计(BySize 只覆盖 16 KiB 以下的 class);每个对象占的堆 = 100 万(或 20 万)个对象保留后 runtime.GC() 之后的 HeapAlloc 增量减去 []any(16 字节/槽)或切片头(24 字节)的开销;基准测试 5 轮取中位数',
     '没有验证:mcache、mcentral、mheap 之间 span 流转的具体过程(只在表里看到了 span 大小,没有观察)、128/192/256 字节处耗时跳变的原因、amd64 与 Linux 上的 class 与耗时、THP 与堆增长对分配的影响、GOGC 对大对象的清零成本、sizespecializedmalloc 的实现'],
    '堆内存分配器')
